   {(parsed.create||parsed.tab==='settings'&&item)&&current&&<form className="card stack" onSubmit={e=>{e.preventDefault();save();}}><h2>{parsed.create?'Create '+noun:'Settings'}</h2>{!editable&&<p>Only an owner, admin or editor can change this item.</p>}<fieldset disabled={!editable||!!pending||saving}><label>Name<input required maxLength={120} value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/></label>{draft.kind==='link'&&<label>Destination URL<input required type="url" maxLength={2048} value={draft.destination} placeholder="https://example.com/page" onChange={e=>setDraft({...draft,destination:e.target.value})}/></label>}<label className="tracked-check"><input type="checkbox" checked={draft.active} onChange={e=>setDraft({...draft,active:e.target.checked})}/>Active public address</label><label className="tracked-check"><input type="checkbox" checked={draft.collection.enabled} onChange={e=>setDraft({...draft,collection:{...draft.collection,enabled:e.target.checked}})}/>Collect basic HTTP requests</label><p className="hint">This operator setting is not visitor consent. Available DNT/GPC and prefetch signals are honored. Raw IP, browser-agent strings and URL queries are not saved.</p>{([['captureReferrer','Record public referrer hostname'],['captureGeography','Record approximate location when locally available'],['excludeBots','Exclude named bots and crawlers']] as const).map(([key,label])=><label className="tracked-check" key={key}><input type="checkbox" checked={draft.collection[key]} onChange={e=>setDraft({...draft,collection:{...draft.collection,[key]:e.target.checked}})}/>{label}</label>)}<button className="btn primary" type="submit">{parsed.create?'Create '+noun:'Save settings'}</button></fieldset>{item&&editable&&<div className="stack">{confirmDelete?<><p role="alert">Delete this {noun}, its recorded requests and public shares? This cannot be undone.</p><div className="row"><button type="button" className="btn danger" disabled={!!pending} onClick={remove}>Confirm delete</button><button type="button" className="btn" onClick={()=>setConfirmDelete(false)}>Cancel</button></div></>:<button type="button" className="btn danger" disabled={!!pending} onClick={()=>setConfirmDelete(true)}>Delete {noun}…</button>}</div>}</form>}
   {item&&parsed.tab==='report'&&<><ScopeForm value={scopeDraft} onChange={setScopeDraft} onApply={applyScope} busy={loading}/>{current?.report&&<TrackedReportView report={current.report} onFilter={(field,value)=>{try{navigate(assetQuery(item.id,filterScope(parsed.scope.canonical,field,value)));}catch{setError('This filter is not available for the current report scope.');}}}/>}</>}
