function ScopeForm({value,onChange,onApply,busy}:{value:string;onChange:(value:string)=>void;onApply:()=>void;busy:boolean}){
 const p=new URLSearchParams(value),set=(key:string,value:string)=>{const next=new URLSearchParams(p);if(value==='')next.delete(key);else next.set(key,value);onChange(next.toString());};
 function location(field:'country'|'region'|'city',state:string){if(state==='known')return;const next=new URLSearchParams(p);next.delete(field);if(state)next.set(field,serializeGeographyKey(field,{state})!);if(field==='country'){next.delete('region');next.delete('city');}if(field==='region')next.delete('city');onChange(next.toString());}
 return <form className="card stack" onSubmit={e=>{e.preventDefault();onApply();}}><div className="tracked-fields"><label>From<input type="date" required value={p.get('from')??''} onChange={e=>set('from',e.target.value)}/></label><label>To<input type="date" required value={p.get('to')??''} onChange={e=>set('to',e.target.value)}/></label><label>Time zone<input required value={p.get('timeZone')??''} placeholder="UTC" onChange={e=>set('timeZone',e.target.value)}/></label><label>Breakdown<select value={p.get('dimension')??'referrer'} onChange={e=>set('dimension',e.target.value)}>{trackedAssetDimensions.map(field=><option key={field} value={field}>{labels[field]}</option>)}</select></label><label>Rows<select value={p.get('limit')??'10'} onChange={e=>set('limit',e.target.value)}>{[5,10,20,100].map(n=><option key={n}>{n}</option>)}</select></label></div><details><summary>Exact filters</summary><div className="tracked-fields">
  <label>Referrer hostname<input value={p.get('referrer')??''} placeholder="example.com" disabled={p.get('referrerMissing')==='1'} onChange={e=>set('referrer',e.target.value)}/></label>
  <label>Recorded channel<select value={p.get('channel')??''} onChange={e=>set('channel',e.target.value)}><option value="">All recorded channels</option><option value="referrer_only">Referrer only</option><option value="not_recorded">Not recorded</option></select></label>
  {(['browser','os','device'] as const).map(field=><label key={field}>{labels[field]}<select value={p.get(field)??''} onChange={e=>set(field,e.target.value)}><option value="">All</option><option value="not-recorded">Not recorded</option>{environmentCatalog[field].map(name=><option key={name}>{name}</option>)}</select></label>)}
  {(['country','region','city'] as const).map(field=>{const key=parseGeographyKey(field,p.get(field));return <label key={field}>{labels[field]}<select value={key?.state??''} onChange={e=>location(field,e.target.value)}><option value="">All</option><option value="not-recorded">Not recorded</option><option value="unknown">Unknown</option>{key?.state==='known'&&<option value="known">{geographyLabel(key)}</option>}</select></label>;})}
  </div><p className="hint">To select a known country, region or city, choose its breakdown and use Filter beside a reported row. Selecting a broader location clears incompatible child locations.</p><label className="tracked-check"><input type="checkbox" checked={p.get('referrerMissing')==='1'} onChange={e=>{const next=new URLSearchParams(p);next.delete('referrer');if(e.target.checked)next.set('referrerMissing','1');else next.delete('referrerMissing');onChange(next.toString());}}/>Referrer not recorded</label><button type="button" className="btn" onClick={()=>{const next=new URLSearchParams(p);for(const key of [...trackedAssetDimensions,'referrerMissing'])next.delete(key);onChange(next.toString());}}>Clear all filters</button></details><button className="btn primary" disabled={busy}>Apply report</button><p className="hint">Filters change this report only. Applying does not edit collection or create a share.</p></form>;
}
// A retention gap is unavailable (hatched), never a zero bar; the current or partly retained day is partial.
const trackedDayPoint=(d:NonNullable<TrackedAssetReport['daily']>[number],index:number):ChartPoint=>({x:index,xLabel:d.date,y:d.requests,state:d.requests===null?'unavailable':d.provisional||d.coverage==='partial'?'partial':'observed',note:d.requests===null?'Unavailable after retention.':d.provisional?'Current partial day.':d.coverage==='partial'?'Partly retained day.':undefined});
function rowLabel(key:string|GeographyKey|null){return key===null?'Not recorded':typeof key==='string'?key==='referrer_only'?'Referrer only':key==='not_recorded'?'Not recorded':key:geographyLabel(key);}
export function TrackedReportView({report,onFilter,showMap=true}:{report:TrackedAssetReport;showMap?:boolean;onFilter?:(field:typeof trackedAssetDimensions[number],key:string|GeographyKey|null)=>void}){
 const noun=report.asset.kind==='link'?'Redirect requests':'Image loads',b=report.breakdown;
 return <section className="stack" aria-label="Tracked asset report"><p>{report.range.from}–{report.range.to} · {report.range.timeZone} · Snapshot <time>{report.asOf}</time></p><p className={report.coverage.status==='complete'?'hint':'banner'} role="status">Retention coverage: {report.coverage.status}.{report.coverage.retainedFrom?' Retained from '+report.coverage.retainedFrom+'.':''} Collection coverage is unknown.</p>{report.summary&&<dl className="analytics-stats"><div className="analytics-stat"><dt className="analytics-stat-label">{noun}</dt><dd className="big-num">{number(report.summary.requests)}</dd></div><div className="analytics-stat"><dt className="analytics-stat-label">Estimated visitors</dt><dd className="big-num">{number(report.summary.estimatedVisitors)}</dd></div><div className="analytics-stat"><dt className="analytics-stat-label">Estimated visits</dt><dd className="big-num">{number(report.summary.estimatedVisits)}</dd></div><div className="analytics-stat"><dt className="analytics-stat-label">Requests without identity</dt><dd className="big-num">{number(report.summary.unidentifiedRequests)}</dd></div></dl>}<p className="hint">{report.method.limitation}</p>
  {report.daily&&<section className="card stack"><h3>Daily {noun.toLowerCase()}</h3><TimeSeriesChart label={`Daily ${noun.toLowerCase()}`} context={`${report.range.from}–${report.range.to} · ${report.range.timeZone}`} kind="bars" fit={report.daily.length>=30&&report.daily.length<=90?'compress':undefined} series={[{id:'requests',label:noun,points:report.daily.map(trackedDayPoint)}]} yDomain={[0,Math.max(1,...report.daily.map(d=>d.requests??0))]} formatY={value=>value.toLocaleString()} xHeader="Date" formatXTick={point=>point.xLabel.slice(5)} tableColumns={[{header:'Estimated visitors',values:report.daily.map(d=>number(d.estimatedVisitors))},{header:'Estimated visits',values:report.daily.map(d=>number(d.estimatedVisits))},{header:'Coverage',values:report.daily.map(d=>`${d.coverage}${d.provisional?' · current partial day':''}${d.skipped?' · skipped local day':''}`)}]} summary="Visitor estimates are not additive across days or groups. Hatched days are unavailable after retention, not zero."/></section>}
  {b&&<section className="card stack"><h3>{labels[b.dimension]}</h3><p>{number(b.returnedRequests)} requests in these rows; {number(b.omittedRequests)} requests in omitted groups. {b.truncated?'Showing the leading '+b.limit+' groups.':'All retained matching groups shown.'}</p>{showMap&&b.dimension==='country'&&!b.truncated&&b.rows.length>0&&<CountryMap rows={b.rows.map(row=>({key:row.key as GeoCountryKey,pageViews:row.requests!,visitors:row.estimatedVisitors}))} countLabel="Requests" preferVisitors={false}/>} {showMap&&b.dimension==='country'&&b.truncated&&<p className="hint">The map needs all matching country groups. Increase Rows or apply a location filter to include them.</p>}<div className="table-wrap" role="region" aria-label={b.dimension==='country'?'Country details':labels[b.dimension]+' request breakdown'} tabIndex={0}><table><thead><tr><th>{labels[b.dimension]}</th><th>{noun}</th><th>Estimated visitors</th><th>Estimated visits</th>{onFilter&&<th>Action</th>}</tr></thead><tbody>{b.rows.map((row,i)=><tr key={i}><th scope="row"><bdi>{rowLabel(row.key)}</bdi></th><td>{number(row.requests)}</td><td>{number(row.estimatedVisitors)}</td><td>{number(row.estimatedVisits)}</td>{onFilter&&<td><button className="btn" onClick={()=>onFilter(b.dimension,row.key??(b.dimension==='referrer'?null:'not-recorded'))}>Filter {rowLabel(row.key)}</button></td>}</tr>)}</tbody></table></div>{!b.rows.length&&<p>{report.coverage.status==='unavailable'?'This range is unavailable under the retention policy.':'No retained requests match this scope.'}</p>}</section>}
 </section>;
}

export function SharedTrackedAssetPanel({search,fragment,entry}:{search:string;fragment:string;entry:string}){
 const [mounted,setMounted]=useState(false);useEffect(()=>setMounted(true),[]);
 const parsed=useMemo(()=>{if(!mounted)return null;try{const p=rawParams(search.replace(/^\?/,''),100);if(p.size!==1||p.get('view')!=='tracked-share')return null;const token=fragment.replace(/^#/,'');if(!/^[A-Za-z0-9_-]{43}$/.test(token))return null;const bytes=atob(token.replaceAll('-','+').replaceAll('_','/')+'=');if(bytes.length!==32||btoa(bytes).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')!==token)return null;return token;}catch{return null;}},[mounted,search,fragment]);
 return mounted?<SharedTrackedInner key={entry+':'+(parsed??'invalid')} token={parsed}/>:<main className="tracked-assets tracked-shared stack"><h1>Shared report</h1><p role="status">Loading shared report…</p></main>;
}
function SharedTrackedInner({token}:{token:string|null}){
 const [data,setData]=useState<{share:{id:string;label:string;sections:typeof trackedShareSections[number][];expiresAt:string};report:TrackedAssetReport}|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),live=useRef(false),controller=useRef<AbortController|null>(null),terminal=useRef(false);
 async function refresh(){if(!token||!live.current||controller.current||terminal.current)return;const ctrl=new AbortController();controller.current=ctrl;setBusy(true);setData(null);setError('');try{const value=z.object({share:z.object({id:trackedUuid,label:text(120),sections:z.array(z.enum(trackedShareSections)).min(1).max(3),expiresAt:stamp}).strict(),report:z.unknown()}).strict().parse(await request('/api/tracked-shares/'+token,ctrl.signal,undefined,true));if(new Set(value.share.sections).size!==value.share.sections.length||Date.parse(value.share.expiresAt)<=Date.now())throw invalid();const report=readTrackedReport(value.report,undefined,undefined,undefined,value.share.sections);if(live.current&&!ctrl.signal.aborted&&!terminal.current)setData({...value,report});}catch(cause){if(live.current&&!ctrl.signal.aborted){setData(null);if(cause instanceof ApiError&&[401,403,404].includes(cause.status))terminal.current=true;setError('This shared report is unavailable, revoked, expired or could not be verified.');}}finally{if(controller.current===ctrl){controller.current=null;if(live.current)setBusy(false);}}}
 useEffect(()=>{live.current=true;if(token)void refresh();const visible=()=>{if(document.visibilityState==='visible')void refresh();else{controller.current?.abort();controller.current=null;setData(null);}},timer=setInterval(()=>{if(document.visibilityState==='visible')void refresh();},30000);document.addEventListener('visibilitychange',visible);return()=>{live.current=false;controller.current?.abort();clearInterval(timer);document.removeEventListener('visibilitychange',visible);};},[token]);
 useEffect(()=>{if(!data)return;let timer:ReturnType<typeof setTimeout>;const expire=()=>{const remaining=Date.parse(data.share.expiresAt)-Date.now();if(remaining>0){timer=setTimeout(expire,Math.min(2147483647,remaining));return;}terminal.current=true;controller.current?.abort();setData(null);setError('This shared report has expired.');};expire();return()=>clearTimeout(timer);},[data]);
 return <main className="tracked-assets tracked-shared stack"><h1>Shared report</h1>{!token?<p role="alert">This share link is malformed. No report was requested. Open the complete link from its owner.</p>:<><button className="btn" disabled={busy||terminal.current} onClick={()=>void refresh()}>Refresh shared report</button>{busy&&<p role="status">Loading shared report…</p>}{error&&<p role="alert" className="alert">{error}</p>}{data&&<><h2><bdi>{data.share.label}</bdi></h2><p><bdi>{data.report.asset.name}</bdi> · Expires <time>{data.share.expiresAt}</time></p><TrackedReportView report={data.report}/></>}<p className="hint">This link permits only its saved report sections and scope. It refreshes while visible; access is checked on every request.</p></>}</main>;
}
